INSERT INTO `events` (`id`, `firm_id`, `name`, `description`, `time_start`, `time_end`) VALUES
(42, 917, 'DOmluvit schůzku na začátek prosince', 'Dobrý den, pane Masopuste, ráda bych to přesunula na začátek prosince, za 14 dní nastupuji do nemocnice.\n\nPokud budete mít čáa, ráda bych se zastavila začátkem prosince u vás ve škole\n\n \n\nMarkéta Stará', '2025-11-24 20:33:00', NULL),
(43, 90, 'CRA - plánovat praxe včas', NULL, '2026-10-12 10:05:00', NULL),
(44, NULL, 'Carl Zeiss - exkurze', 'Echt Praxe 2026.\nExnerová s E2, \n 15.6. 2026.  od 9h', '2026-06-15 09:00:00', NULL),
(45, 176, 'Irqf nabídka přednášek', 'Ozvat se Ivona Spurná <ivona.spurna@iqrfalliance.org>. Email z 15.4.26', '2026-09-14 10:26:00', NULL),
(46, 880, 'Plány na podzim', 'Sejít se a představit ná program.', '2026-06-03 11:51:00', NULL),
(47, 1002, 'pozvat na veletrhu: Facility management na NEWTON University ', 'email z 23.4.26', '2026-01-17 09:00:00', NULL),
(48, 918, 'Pozvat na předváděčku projektů', 'Vypoisovali vylstní soutěž, ale v březnu:/', '2026-09-28 12:50:00', NULL),
(49, 604, 'Domluvit přednášky', 'Preferují propagaci techniky mezi žáky.\n2.r - vhled do problematiky - 02/27\n3.r - reklama na WS, WS - 10/26', '2026-09-21 09:42:00', NULL),
(50, 880, 'Naplánovat schůzku', 'e-mail 5.6.\nsejít se na začátku září\n', '2026-08-28 12:29:00', NULL),
(51, 126, 'Ze schůzky z elektroline - pro nový školní rok:', 'elektroline - vystavěl, čop, Daniel Dvořák. Jan Stejskal, Jakub Hnízdo\n\n4-5 se přihlásilo.\nVelký úspěch.\n\nchtzějí reference\n\n\nOzývají se z přechozích let.\n\nčížkovsý - dělá tu a pozvat si ho.', '2026-08-24 14:27:00', NULL);
