INSERT INTO `meets` (`id`, `firm_id`, `date_time`, `notes`) VALUES
(5, 1, '2024-08-31 18:31:00', 'OZVAT SE!'),
(15, 681, '2024-09-12 13:00:00', 'Vysvětlil jsem náš program. Čekám na návrhy obsahu WS. Viděl jsem výrobní linku'),
(16, 684, '2024-10-02 19:23:00', '\nuž k nim chodí 9 žáků z jiné školy 2d jednou za 14 dní\nKomponenty pro bezpilotní letadla - palubní počíta, pohon, navigace, vysílačka\n'),
(17, 264, '2024-09-30 13:15:00', 'školení pro učitele a to proškolí. Pak certifikují vyučující.\nK existujímu stroji je schopen dodat virtuální dvojče ke stroji.\nPřipravují vzděl. obsah pro učitel\nRošíření studia...\nProgramování CNC strojů\ndemoverze strojů - sw, 95% sleva \nPlatí si učitel z VŠ dělá zajimavé\nMohou to učit i fyzikáři - kinematik. hm. bodu.\nSinumeric CUP\nPosalt naše TP. \nProdiskutovat, jak to napojit na výuku.\nDo 14.10. si říct, co bude.\n'),
(18, 728, '2025-04-11 20:34:00', 'scůzka: spolupracuje s 5 školama, dě,ají škokení i pro učitele\nučitele\nozvat se v ziří\nposlat cv\n\n'),
(19, 790, '2025-05-06 15:10:00', 'Přesnáška v červnu, postaveno na Unity. Jde o herní desing- návrh herního prostředí. Zkusti přidat do výuky. Další přednášky a WD od září.'),
(20, 794, '2025-06-04 12:18:00', 'Oběd - seznamovací schůzka'),
(21, 771, '2025-04-07 15:15:00', 'Seznamovací schůzka'),
(22, 126, '2025-02-06 13:00:00', 'Schůzka s Mrázkem - jednání od daru.'),
(23, 767, '2025-02-28 11:10:00', 'Seznamovací schůzka'),
(24, 695, '2025-01-29 15:30:00', 'Přišel na Elektrokomisi'),
(25, 634, '2025-01-14 15:30:00', 'Telefoná s Řehákem'),
(26, 187, '2025-04-10 17:30:00', 'Telefonát - jak budeme spolupracovat.'),
(27, 706, '2024-12-04 13:00:00', 'Seznamovací online pokec.'),
(28, 246, '2024-10-24 14:15:00', 'Seznamovací schůzka'),
(29, 599, '2024-10-09 13:30:00', 'Informační schůzka - plánování dalších akcí.'),
(30, 303, '2024-10-09 13:00:00', 'Spolupráce pro školní rok 2024/2025 + \"Den s Networkem'),
